import { useEffect, useRef, useState } from "preact/hooks";
import { levelOptions } from "./level";
import { placementStyle, usePlacement } from "./popover";

type LevelChipProps = {
  level: number;
  contentLevels: readonly number[];
  onPick: (level: number) => void;
};

const LIST_MAX_PX = 440;

export function LevelChip({ level, contentLevels, onPick }: LevelChipProps) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const currentRef = useRef<HTMLButtonElement>(null);
  const placement = usePlacement(open, rootRef, LIST_MAX_PX);

  useEffect(() => {
    if (!open || !placement) return;
    currentRef.current?.scrollIntoView({ block: "nearest" });
    const close = (event: PointerEvent) => {
      if (event.target instanceof Node && rootRef.current?.contains(event.target)) return;
      setOpen(false);
    };
    window.addEventListener("pointerdown", close);
    return () => window.removeEventListener("pointerdown", close);
  }, [open, placement]);

  return (
    <div class="level" ref={rootRef}>
      <button
        type="button"
        class="level-chip"
        aria-label={`Zoom level ${level}`}
        aria-expanded={open}
        aria-haspopup="listbox"
        title="Zoom level: 0 is the starting zoom, negative is zoomed in"
        onClick={() => setOpen(!open)}
      >
        {level}
      </button>
      {open && (
        <div
          class="level-list"
          data-side={placement?.side}
          style={placementStyle(placement)}
          role="listbox"
          aria-label="Zoom levels"
        >
          {levelOptions(level, contentLevels).map((option) => (
            <button
              key={option.level}
              ref={option.current ? currentRef : null}
              type="button"
              role="option"
              aria-selected={option.current}
              aria-label={`Level ${option.level}${option.hasContent ? ", has strokes" : ""}`}
              class="level-option"
              onClick={() => {
                setOpen(false);
                onPick(option.level);
              }}
            >
              <span>{option.level}</span>
              {option.hasContent && <span class="level-dot" aria-hidden="true" />}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
import { MAX_LEVEL, MIN_LEVEL, nativeLevel } from "@stallion/geometry";

export type LevelOption = { level: number; current: boolean; hasContent: boolean };

export const LEVEL_ANIMATION_MS = 250;

export const levelOf = (zoom: number): number => nativeLevel(zoom);

export const zoomForLevel = (level: number): number => 2 ** -level;

export function levelOptions(current: number, contentLevels: Iterable<number>): LevelOption[] {
  const content = new Set(contentLevels);
  const levels = [current, ...content];
  const deepest = Math.max(MIN_LEVEL, Math.min(...levels) - 1);
  const shallowest = Math.min(MAX_LEVEL, Math.max(...levels) + 1);
  return Array.from({ length: shallowest - deepest + 1 }, (_, index) => {
    const level = deepest + index;
    return { level, current: level === current, hasContent: content.has(level) };
  });
}

export const easeOut = (t: number): number => 1 - (1 - t) ** 3;
import type { RefObject } from "preact";
import { useLayoutEffect, useState } from "preact/hooks";
import { type Placement, placePopover } from "./toolbar-layout";

export const usePlacement = (
  open: boolean,
  anchorRef: RefObject<HTMLElement>,
  desiredHeight: number,
): Placement | undefined => {
  const [placement, setPlacement] = useState<Placement | undefined>(undefined);

  useLayoutEffect(() => {
    if (!open) return;
    const place = () => {
      const anchor = anchorRef.current;
      if (!anchor) return;
      setPlacement(placePopover(anchor.getBoundingClientRect(), window.innerHeight, desiredHeight));
    };
    place();
    window.addEventListener("resize", place);
    return () => window.removeEventListener("resize", place);
  }, [open, anchorRef, desiredHeight]);

  return open ? placement : undefined;
};

export const placementStyle = (placement: Placement | undefined) =>
  placement ? { maxHeight: `${placement.maxHeight}px` } : { visibility: "hidden" as const };
import { PAPER } from "./surface";

export const THUMBNAIL_WIDTH = 160;

const BLANK_TOLERANCE = 4;

const paperRgb = (() => {
  const hex = PAPER.replace("#", "");
  return {
    r: Number.parseInt(hex.slice(0, 2), 16),
    g: Number.parseInt(hex.slice(2, 4), 16),
    b: Number.parseInt(hex.slice(4, 6), 16),
  };
})();

const isBlank = (data: Uint8ClampedArray): boolean => {
