      ...base,
      type: "Sticky",
      text: "Buy milk\nand   a very long list of things",
    } as StallionObject),
  ).toBe("Note: Buy milk and a very long l…");
  expect(objectLabel({ ...base, type: "Text", text: "Hello" } as StallionObject)).toBe(
    "Text: Hello",
  );
