import { writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { chromium, devices } from "playwright";
import { routeAccessHeaders } from "../npm-scripts/env.mjs";

const ORIGIN = process.argv[2] ?? "https://stallion.kattebak.fyi";
const DIR = join(homedir(), "development", ".tmp", "stallion-levels");
const boardId = () => `levels-${Date.now().toString(36)}`;
const problems = [];

const watch = (page, label) => {
  page.on("console", (m) => m.type() === "error" && problems.push(`${label} console: ${m.text()}`));
  page.on("pageerror", (e) => problems.push(`${label} pageerror: ${e.message}`));
};

const drag = async (page, from, to, steps = 12) => {
  await page.mouse.move(from.x, from.y);
  await page.mouse.down();
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    await page.mouse.move(
      from.x + (to.x - from.x) * t,
      from.y + (to.y - from.y) * t + Math.sin(t * Math.PI) * 30,
    );
  }
  await page.mouse.up();
  await page.waitForTimeout(300);
};

const chipLevel = async (page) =>
  Number(await page.locator(".level-chip").first().innerText());

const zoomOutTo = async (page, target, at) => {
  await page.mouse.move(at.x, at.y);
  for (let i = 0; i < 60 && (await chipLevel(page)) < target; i++) {
    await page.mouse.wheel(0, 120);
    await page.waitForTimeout(60);
  }
  await page.waitForTimeout(400);
};

const draw = async (page, tool) => {
  const button = page.getByRole("button", { name: tool, exact: true });
  if (await button.isVisible()) await button.click();
};

const run = async (browser, profile, label) => {
  const context = await browser.newContext({ ...profile, colorScheme: "light" });
  await routeAccessHeaders(context, new URL(ORIGIN).origin);
  const page = await context.newPage();
  watch(page, label);
  await page.goto(`${ORIGIN}/b/${boardId()}`, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
  await page.waitForTimeout(1500);
  const vp = page.viewportSize();
  const cx = vp.width / 2;
  const cy = vp.height / 2;
  const more = page.getByRole("button", { name: "More tools" });
  if (await more.isVisible()) await more.click();
  await drag(page, { x: cx - 260, y: cy - 60 }, { x: cx - 80, y: cy + 40 });
  await draw(page, "Rectangle");
  await drag(page, { x: cx - 40, y: cy - 60 }, { x: cx + 120, y: cy + 60 }, 6);
  await draw(page, "Rectangle");
  await draw(page, "Sticky note");
  await page.mouse.click(cx + 240, cy);
  await page.waitForTimeout(500);
  await page.keyboard.type("Groceries for the weekend trip");
  await page.waitForTimeout(300);
  await page.keyboard.press("Escape");
  await draw(page, "Pan tool");
  await page.waitForTimeout(800);
  const fewer = page.getByRole("button", { name: "Fewer tools" });
  if (await fewer.isVisible()) await fewer.click();
  await page.screenshot({ path: join(DIR, `${label}-1-drawn.png`) });
  await zoomOutTo(page, 2, { x: cx, y: cy });
  const level = await chipLevel(page);
  await page.locator(".level-chip").first().click();
  await page.locator(".level-list").waitFor({ state: "visible" });
  await page.waitForTimeout(300);
  await page.locator('.level-option[data-level="0"]').hover();
  await page.waitForTimeout(800);
  const flyout = page.locator(".level-flyout");
  await flyout.waitFor({ state: "visible", timeout: 3000 });
  const rows = await flyout.locator(".level-object").allInnerTexts();
  const side = await flyout.getAttribute("data-side");
  const imgs = await flyout
    .locator("img.level-preview")
    .evaluateAll((els) => els.map((el) => el.complete && el.naturalWidth > 0));
  const firstRow = flyout.locator(".level-object").first();
  await firstRow.hover();
  await page.waitForTimeout(300);
  await page.screenshot({ path: join(DIR, `${label}-2-popout.png`) });
  const target = await firstRow.innerText();
  await firstRow.click();
  await page.waitForTimeout(900);
  const after = await chipLevel(page);
  const listOpen = await page.locator(".level-list").isVisible();
  await page.screenshot({ path: join(DIR, `${label}-3-jumped.png`) });
  await context.close();
  return { label, zoomedTo: level, rows, side, previewsLoaded: imgs, clicked: target, levelAfterJump: after, listOpen };
};

const browser = await chromium.launch({ headless: true });
const results = [];
results.push(await run(browser, devices["Desktop Chrome"] && { ...devices["Desktop Chrome"], viewport: { width: 1280, height: 800 } }, "desktop"));
results.push(await run(browser, devices["Galaxy Tab S9"], "tablet"));
await browser.close();
writeFileSync(join(DIR, "result.json"), JSON.stringify({ results, problems }, null, 2));
console.log(JSON.stringify({ results, problems }, null, 2));
process.exit(problems.length > 0 ? 1 : 0);
